function snapshot(){undoState={trip:C.clone(state.trip),originalTrip:C.clone(state.originalTrip),expenses:C.clone(state.expenses),prep:C.clone(state.prep),settings:C.clone(state.settings)};undoStack.push(undoState);if(undoStack.length>20)undoStack.shift();updateUndo();}
function updateUndo(){const b=$('#undoBtn');if(b){b.disabled=!undoStack.length;b.title='이 세션에서 최근 '+undoStack.length+'개 변경 되돌리기';}}
function undo(){if(!undoStack.length)return;if($('#sheet').open&&isSheetDirty()){toast('입력 중인 내용을 먼저 저장하거나 닫아 주세요.');return;}const prev=undoStack.pop();undoState=undoStack.at(-1)||null;Object.assign(state,prev);if(state.trip)C.bindRouteAnchors(state.trip);delayProposal=null;log('직전 변경을 되돌림');persist();render(false);updateUndo();toast('이전 상태로 되돌렸어요.');}
function mutate(fn,message){snapshot();const before=undoStack.at(-1);try{if(state.trip)C.bindRouteAnchors(state.trip);fn();if(state.trip)C.validateTrip(state.trip);}catch(e){Object.assign(state,before);undoStack.pop();undoState=undoStack.at(-1)||null;updateUndo();throw e;}delayProposal=null;log(message);persist();render(false);toast(message,true);}
function validateBackup(b){
 if(b?.schema!==2||b.kind!=='taipei-app-backup')throw Error('v2 백업 파일이 아닙니다.');
 if(b.trip)C.validateTrip(b.trip);if(b.originalTrip)C.validateTrip(b.originalTrip);
 if(!Array.isArray(b.expenses)||b.expenses.length>10000||!b.expenses.every(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&Number.isFinite(x.twd)&&x.twd>0&&x.twd<1e9&&['cash','card','easy'].includes(x.method)&&Number.isFinite(x.time)))throw Error('지출 내역이 손상되었습니다.');
 const s={...settingsDefault,...b.settings};for(const k of ['whisky','gifts','fee','minRest','reservationBuffer'])if(!Number.isFinite(s[k])||s[k]<0||s[k]>1e9)throw Error('설정 금액이 잘못되었습니다.');
 if(!Number.isFinite(s.cashAdded)||Math.abs(s.cashAdded)>1e9)throw Error('현금 변동액이 잘못되었습니다.');
 if(!Number.isFinite(s.manualRate)||s.manualRate<=0||s.manualRate>1000)throw Error('수동 환율이 잘못되었습니다.');
 if(s.cashOpening!==null&&(!Number.isFinite(s.cashOpening)||s.cashOpening<0))throw Error('현금 잔액이 잘못되었습니다.');
 for(const k of ['motion','haptics'])s[k]=s[k]===true;
 // v2's default-true flag is NOT evidence of opt-in consent.
 s.autoDelay=s.autoDelay===true&&s.autoDelayConsentVersion===1;
 if(s.minRest<10||s.minRest>120||s.reservationBuffer>180)throw Error('휴식·예약 보호시간 범위를 확인하세요.');
 for(const x of b.expenses)for(const k of ['krwAtEntry','confirmedKrw','raw','rateSnapshot'])if(x[k]!==undefined&&x[k]!==null&&(!Number.isFinite(x[k])||x[k]<0||x[k]>1e12))throw Error('지출 원화·입력 환율이 잘못되었습니다.');
 if(!['manual','auto'].includes(s.rateMode)||!['system','light','dark'].includes(s.theme))throw Error('설정 형식이 잘못되었습니다.');
 if(b.fx&&(!Number.isFinite(b.fx.rate)||b.fx.rate<=0||!Number.isFinite(b.fx.quotedAt)||!Number.isFinite(b.fx.fetchedAt)))throw Error('환율 기록이 잘못되었습니다.');
 return {...emptyState(),...b,settings:s,expenses:b.expenses.map(C.normalizeExpense),prep:b.prep&&typeof b.prep==='object'&&!Array.isArray(b.prep)?b.prep:{},logs:Array.isArray(b.logs)?b.logs.filter(x=>x&&Number.isFinite(x.time)&&typeof x.message==='string').slice(0,80):[]};
}
/* Source HTML is displayed only through a strict allow-list; imported content never executes. */
function rich(raw){
 const doc=new DOMParser().parseFromString('<div>'+String(raw||'')+'</div>','text/html'),root=doc.body.firstElementChild;
 const allowed=new Set('DIV SPAN P B STRONG EM I SMALL BR UL OL LI H2 H3 H4 DETAILS SUMMARY TABLE THEAD TBODY TFOOT TR TH TD DL DT DD A BUTTON'.split(' '));
 for(const el of [...root.querySelectorAll('*')]){
  if(!allowed.has(el.tagName)){if(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','IMG','SVG','MATH','LINK','META','FORM','INPUT'].includes(el.tagName))el.remove();else el.replaceWith(...el.childNodes);continue;}
  for(const a of [...el.attributes])if(!['class','colspan','rowspan','data-term','href','open'].includes(a.name))el.removeAttribute(a.name);
  if(el.tagName==='A'){try{const u=new URL(el.getAttribute('href')||'',location.href);if(!['https:','http:'].includes(u.protocol))el.removeAttribute('href');else{el.href=u.href;el.target='_blank';el.rel='noopener noreferrer';}}catch(e){el.removeAttribute('href');}}
  if(el.tagName==='BUTTON')el.type='button';
 }
 const walker=doc.createTreeWalker(root,NodeFilter.SHOW_TEXT);const texts=[];while(walker.nextNode())texts.push(walker.currentNode);
 const re=/NT\$\s*([\d,]+(?:\.\d+)?)(?:\s*[~～–—-]\s*(?:NT\$\s*)?([\d,]+(?:\.\d+)?))?/g;
 for(const t of texts){let m,last=0,changed=false;const f=doc.createDocumentFragment();while((m=re.exec(t.textContent))){changed=true;f.append(t.textContent.slice(last,m.index));const span=doc.createElement('span');span.className='dual-inline';const a=Number(m[1].replaceAll(',','')),b=m[2]?Number(m[2].replaceAll(',','')):null;span.textContent=m[0]+' (약 '+fmt(krw(a))+(b!==null?'~'+fmt(krw(b)):'')+'원)';f.append(span);last=re.lastIndex;}if(changed){f.append(t.textContent.slice(last));t.replaceWith(f);}}
 return root.innerHTML;
}
function sourceNote(){return '<p class="source-note">사용자 원본 자료를 표시합니다. 예약·영업·요금·규정은 이번 앱 제작에서 재검증하지 않았습니다. 원본의 과거 원화 예시와 현재 환산액이 다를 수 있어요.</p>';}
