function sheetFingerprint(){return JSON.stringify($$('#sheetContent form input,#sheetContent form select,#sheetContent form textarea').map(e=>[e.name,e.value,e.checked,e.disabled]));}
function isSheetDirty(){return $('#sheet').open&&sheetDirty;}
