function showSheet(title,body){clearTimeout(closeTimer);const dlg=$('#sheet');if(!dlg.open){dialogFocus=document.activeElement;dlg.showModal();document.body.style.overflow='hidden';}dlg.classList.remove('closing');dlg.style.transform='';$('#dirtyGuard')?.remove();$('#sheetTitle').textContent=title;$('#sheetContent').innerHTML=body;dlg.scrollTop=0;markSheetClean();$('#closeSheet').focus();}
function protectDraft(){if($('#dirtyGuard'))return;draftFocus=document.activeElement;const guard=document.createElement('div');guard.id='dirtyGuard';guard.className='notice warn';guard.setAttribute('role','alert');guard.innerHTML='<b>아직 저장하지 않은 입력이 있습니다.</b><p>닫으면 입력이 사라집니다.</p><div class="actions"><button type="button" class="btn primary" id="keepDraft">계속 편집</button><button type="button" class="btn danger" id="discardDraft">버리고 닫기</button></div>';$('.sheet-head').after(guard);$('#keepDraft').onclick=()=>{guard.remove();if(draftFocus?.isConnected)draftFocus.focus({preventScroll:true});};$('#discardDraft').onclick=()=>closeSheet(false,true);$('#keepDraft').focus({preventScroll:true});guard.scrollIntoView({block:'nearest',behavior:'instant'});}
function closeSheet(immediate=false,force=false){const dlg=$('#sheet');if(!dlg.open)return;dlg.style.transform='';dlg.classList.remove('sheet-dragging');if(!force&&isSheetDirty()){protectDraft();return;}markSheetClean();dlg.classList.add('closing');clearTimeout(closeTimer);closeTimer=setTimeout(()=>{dlg.close();dlg.classList.remove('closing');document.body.style.overflow='';if(dialogFocus?.isConnected)dialogFocus.focus({preventScroll:true});},immediate?0:160);}
$('#closeSheet').onclick=()=>closeSheet();$('#sheet').addEventListener('cancel',e=>{e.preventDefault();closeSheet()});$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){const r=e.target.getBoundingClientRect();if(e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)closeSheet();}});
$('#sheet').addEventListener('input',updateSheetDirty);$('#sheet').addEventListener('change',updateSheetDirty);
window.addEventListener('beforeunload',e=>{if(isSheetDirty()){e.preventDefault();e.returnValue='';}});
let sheetDrag=null;
const grab=$('.grab');grab.onclick=()=>{};
grab.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0)return;sheetDrag={id:e.pointerId,y:e.clientY,start:Date.now(),dy:0};grab.setPointerCapture(e.pointerId);$('#sheet').classList.add('sheet-dragging');e.preventDefault();});
grab.addEventListener('pointermove',e=>{if(!sheetDrag||sheetDrag.id!==e.pointerId)return;sheetDrag.dy=Math.max(0,e.clientY-sheetDrag.y);$('#sheet').style.transform='translateY('+sheetDrag.dy+'px)';e.preventDefault();});
function endSheetDrag(e,cancel=false){if(!sheetDrag||e.pointerId!==sheetDrag.id)return;const d=sheetDrag;sheetDrag=null;$('#sheet').style.transform='';$('#sheet').classList.remove('sheet-dragging');if(grab.hasPointerCapture(e.pointerId))grab.releasePointerCapture(e.pointerId);if(!cancel&&(d.dy>=90||d.dy>=45&&d.dy/Math.max(1,Date.now()-d.start)>.6))closeSheet();}
grab.addEventListener('pointerup',e=>endSheetDrag(e));grab.addEventListener('pointercancel',e=>endSheetDrag(e,true));
