const navs=[['home','홈','<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>'],['plan','일정','<path d="M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1"/>'],['money','예산','<rect x="3" y="5" width="18" height="15" rx="2"/><circle cx="12" cy="12.5" r="3"/>'],['places','장소','<path d="M12 22S4 15 4 9a8 8 0 0 1 16 0c0 6-8 13-8 13Z"/><circle cx="12" cy="9" r="2.5"/>'],['more','더보기','<path d="M5 6h14M5 12h14M5 18h14"/>']];
