function homeView(){
 const {now,running,scheduled,next,fixed,items}=currentContext(),focus=running||scheduled||next,d=selectedDay(),di=C.dayItems(state.trip,d.id),done=di.filter(x=>x.status==='done').length,skip=di.filter(x=>!C.included(x)).length,b=C.budget(state.trip,state.settings,state.expenses),pd=(state.trip.prep||[]).filter(x=>state.prep[x.id]).length;
 if(!items.length)return '<div class="card"><h2>일정을 추가해 주세요.</h2><button class="btn primary" data-action="add">새 일정 추가</button><button class="btn" data-action="restore-original">원본 복원</button></div>';
 const before=now<Math.min(...items.map(x=>x.start)),after=now>Math.max(...items.map(x=>x.end));
 const label=running?'내가 시작한 일정':before?'출발 전, 준비할 시간':after?'여행 기록':scheduled?'시간표 기준 · 방문 여부 미확인':'다음 예정 일정';
 const title=before?`출발까지 D-${Math.ceil((items[0].start-now)/C.DAY)}`:focus?.title||'여행을 마쳤어요';
 return `<div class="quick-actions"><button class="btn primary" data-action="conversation">여행 회화 · 중국어 / 영어</button>${state.trip.places.hotel?'<button class="btn" data-action="place-info" data-place="hotel">내 숙소 주소</button>':''}</div><div class="hero"><span class="pill">${esc(label)}</span><h2>${esc(title)}</h2><p class="small">${focus?`${scheduleTime(focus)} · ${focus.tz===9?'한국':'대만'} 시각`:'완료 기록과 지출을 백업해 주세요.'}</p><div class="actions">${before?'<button class="btn" data-action="prep">준비·예약 확인</button>':focus?`<button class="btn" data-action="reveal" data-id="${esc(focus.id)}">일정 자세히</button>${focus.place||focus.to?`<button class="btn secondary" data-action="route" data-id="${esc(focus.id)}">길찾기</button>`:''}`:''}</div></div>
 ${running?`<div class="notice"><b>진행 기록 중</b> · ${stamp(running.actualStart,running.tz)} 시작<br><span class="small">끝나면 완료를 눌러 주세요. 체크하지 않은 과거 일정은 지연으로 단정하지 않아요.</span><div class="actions" style="margin-top:9px"><button class="btn primary" data-action="done" data-id="${esc(running.id)}">완료</button><button class="btn" data-action="delay" data-id="${esc(running.id)}">지연 확인</button>${nextPlace(running)?`<button class="btn" data-action="route" data-id="${esc(nextPlace(running).id)}">다음 장소 길찾기</button>`:''}</div></div>`:''}
 ${fixed?`<div class="card"><div class="row"><b>다음 고정 일정</b><span class="pill gold">시간 보호</span></div><h3 style="margin-top:12px">${esc(fixed.title)}</h3><div class="row"><span class="small">${scheduleTime(fixed)} · 원본 정보 확인 필요</span><b class="mono">${fixed.start>now?untilText(fixed.start-now):'진행 시간'}</b></div><button class="btn full" style="margin-top:12px" data-action="reveal" data-id="${esc(fixed.id)}">예약 일정 보기</button></div>`:''}
 <div class="section-title"><h3>여행 경비 한눈에</h3><button class="btn smallbtn" data-action="expense">지출 입력</button></div><div class="card"><div class="mini-label">전체 예상 · 항공·숙소 제외</div>${money(b.planned,true)}<div class="sep"></div><div class="grid2"><div><div class="mini-label">실제 기록한 지출</div>${actualMoney(b)}</div><div><div class="mini-label">남은 예산 · 현재환산</div>${money(b.remaining)}</div></div></div>
 ${state.trip.items.some(x=>C.included(x)&&x.k==='m'&&x.routeStale)?'<div class="notice warn" style="margin-top:12px">이동시간·요금 미확정 구간은 예상 예산에서 제외했습니다. 실제 총액은 달라질 수 있습니다.</div>':''}
 <div class="grid2" style="margin-top:12px"><div class="card"><div class="mini-label">현금 잔액</div>${state.settings.cashOpening===null?'<button class="btn smallbtn" data-action="cash">초기 현금 입력</button>':money(b.cashRemaining)}</div><div class="card"><div class="mini-label">권장 준비 현금</div>${money(b.cashRecommended)}<div class="small">원본 예산식 · 여유 10%</div></div></div>
 <div class="section-title"><h3>${esc(d.chip)} 일정 진행</h3><button class="btn smallbtn" data-action="plan">전체 일정</button></div><div class="card"><div class="row"><b>${done} / ${di.length-skip} 완료</b><span class="small">${skip} 건너뜀</span></div><div class="progress"><i style="width:${done/Math.max(1,di.length-skip)*100}%"></i></div><div class="small" style="margin-top:10px">준비·예약 체크 ${pd} / ${(state.trip.prep||[]).length}</div></div>`;
}
function dayBar(){return `<div class="days">${state.trip.days.map(d=>`<button type="button" class="day" data-day="${esc(d.id)}" aria-pressed="${d.id===curDay}"><b>${esc(d.chip)}</b><small>${esc(d.dow)}${d.hol?' · '+esc(d.hol):''}</small></button>`).join('')}</div>`;}
function eventHTML(x){const isOpen=openCards.has(x.id),label={pending:'',running:'진행 중',done:'완료',skipped:'건너뜀',cancelled:'취소' }[x.status];
 const place=state.trip.places[x.place||x.to];
 return `<article class="event ${x.k==='m'?'move':''} ${x.fixed?'fixed':''} ${x.status} ${isOpen?'open':''}" id="event-${esc(x.id)}"><button class="event-summary" data-action="toggle-event" data-id="${esc(x.id)}" aria-expanded="${isOpen}" aria-controls="body-${esc(x.id)}"><span class="event-time">${x.timeStatus==='target'?stamp(x.start,x.tz)+'<small>목표</small>':x.routeStale?'미확정':stamp(x.start,x.tz)}<small>${x.routeStale?'확인 필요':stamp(x.end,x.endTz)}</small>${x.tz!==x.endTz?'<small>시차 반영</small>':''}</span><span class="event-main"><span class="event-name">${esc(x.title)}</span><span class="event-sub" style="display:block">${C.protectedItem(x)?'<span class="pill gold">시간 보호</span> ':''}${x.reservationStatus==='unconfirmed'?'<span class="pill">예약 미확정</span> ':''}${label?`<span class="pill ${x.status==='running'?'good':''}">${label}</span> `:''}${x.buffer?'<span class="pill">휴식 버퍼</span> ':''}${x.k==='m'?'이동 · ':''}${esc(x.sub||'')}</span><span class="event-money" style="display:block">${x.routeStale?'동선 변경 · 시간/요금 미확정':x.cost>0?inlineMoney(x.cost):(x.pay==='결제완료'?'사전 결제':'예상 비용 0원 · NT$0')}</span></span><span class="chevron" aria-hidden="true">⌄</span></button>
 ${editing?`<div class="edit-tools"><button class="btn smallbtn" data-action="edit" data-id="${esc(x.id)}">편집</button>${x.k==='s'?`<button class="btn smallbtn" data-action="duplicate" data-id="${esc(x.id)}">복제</button>`:''}${C.stop(x)&&!C.protectedItem(x)&&x.status==='pending'?`<button type="button" class="btn smallbtn drag-handle" data-drag-id="${esc(x.id)}" aria-label="${esc(x.title)} 끌어서 순서 변경" title="손잡이를 끌어 정렬 · 방향키 또는 ↑↓ 버튼도 사용 가능">↕</button><button class="btn smallbtn" data-action="up" data-id="${esc(x.id)}" aria-label="${esc(x.title)} 위로">↑</button><button class="btn smallbtn" data-action="down" data-id="${esc(x.id)}" aria-label="${esc(x.title)} 아래로">↓</button>`:''}<button class="btn smallbtn danger" data-action="delete" data-id="${esc(x.id)}">삭제</button></div>`:''}
 <div class="expand" id="body-${esc(x.id)}" ${isOpen?'':'inert'}><div><div class="event-body"><details class="source-details"><summary>상세 안내</summary><div class="rich">${rich(x.body||'')}${x.steps?.length?`<ol>${x.steps.map(s=>'<li>'+rich(s)+'</li>').join('')}</ol>`:''}${x.kv?.length?`<dl>${x.kv.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${rich(v)}</dd>`).join('')}</dl>`:''}${x.tip?`<div class="tip">${rich(x.tip)}</div>`:''}${x.alt?`<div class="small">${rich(x.alt)}</div>`:''}</div></details>
 ${place?`<button class="btn place-summary" data-action="place-info" data-id="${esc(x.id)}" data-place="${esc(x.place||x.to)}">장소 정보 · ${esc(place.n)}</button>`:''}${x.notes?`<div class="notice" style="margin-top:10px"><b>내 메모</b><br>${esc(x.notes).replaceAll('\n','<br>')}</div>`:''}
 ${x.routeStale?'<div class="notice warn">새 이동시간·요금은 미확정입니다. 표시에 쓰는 빈 시간은 이동시간 추정이 아닙니다. 지도에서 확인 후 편집 화면의 경로 확인 체크를 선택하세요.</div>':''}
 <div class="actions">${C.active(x)?`<button class="btn primary" data-action="${x.status==='running'?'done':'start'}" data-id="${esc(x.id)}">${x.status==='running'?'완료':'지금 시작'}</button>${x.status!=='running'?`<button class="btn" data-action="done" data-id="${esc(x.id)}">완료 표시</button>`:''}<button class="btn" data-action="skip" data-id="${esc(x.id)}">건너뛰기</button><button class="btn danger" data-action="cancel-item" data-id="${esc(x.id)}">취소 상태</button>`:`<button class="btn" data-action="unmark" data-id="${esc(x.id)}">상태 되돌리기</button>`}${x.place||x.to?`<button class="btn" data-action="route" data-id="${esc(x.id)}">길찾기</button>`:''}</div><div class="actions">${place&&TaipeiUX.resolveDriver(x.place||x.to,place,x).eligible?`<button class="btn" data-action="driver" data-id="${esc(x.id)}" data-place="${esc(x.place||x.to)}">택시 기사님께 보여주기</button>`:''}<button class="btn" data-action="expense" data-id="${esc(x.id)}">지출</button><button class="btn" data-action="edit" data-id="${esc(x.id)}">시간·장소·메모</button>${C.active(x)?`<button class="btn" data-action="delay" data-id="${esc(x.id)}">지연 조정</button>`:''}</div></div></div></div></article>`;
}
function planView(){const d=selectedDay(),items=C.dayItems(state.trip,d.id),done=items.filter(x=>x.status==='done').length,skip=items.filter(x=>!C.included(x)).length,total=items.filter(C.knownCost).reduce((s,x)=>s+x.cost,0),issues=C.conflicts(state.trip,d.id);
 return `${dayBar()}<div class="row" style="margin-bottom:10px"><span class="pill">${d.tz===9?'한국':'대만'} 시각 · 좌우로 날짜 이동</span><button class="btn smallbtn" data-action="editmode">${editing?'편집 완료':'일정 편집'}</button></div><h2 style="font-size:21px">${esc(d.title)}</h2><div class="row"><span class="small">${done} 완료 · ${skip} 건너뜀 / ${items.length}개</span><b class="event-money">${inlineMoney(total)}</b></div><div class="progress"><i style="width:${done/Math.max(1,items.length-skip)*100}%"></i></div><div class="actions" style="margin:12px 0"><button class="btn" data-action="add">일정 추가</button><button class="btn" data-action="route-day">하루 동선</button></div>
 ${issues.length?`<div class="notice warn">시간이 겹치는 구간 ${issues.length}건이 있습니다. 원본의 겹침도 포함됩니다. <button class="btn smallbtn" data-action="conflicts">확인</button></div>`:''}
 ${d.notices?.length?`<details class="card rich"><summary>이날 요약·주의사항 · 원본 안내</summary>${d.facts?.length?`<div class="stack" style="margin-top:12px">${d.facts.map(f=>`<div><b>${esc(f[0])}: ${esc(f[1])}</b><div class="small">${rich(esc(f[2]))}</div></div>`).join('')}</div>`:''}${d.notices.map(n=>`<p style="margin-top:12px">${rich(n[1])}</p>`).join('')}${sourceNote()}</details>`:''}
 <div class="timeline" id="timeline">${items.map(eventHTML).join('')}</div>${d.alt?`<details class="card rich" style="margin-top:14px"><summary>원본 대안 일정</summary>${[].concat(d.alt).map(a=>`<h4>${esc(a.title)}</h4>${rich(a.body)}`).join('')}</details>`:''}<div class="source-note">시간·주소·내용은 카드에서 수정할 수 있어요. 이동 경로 변경 후 소요시간은 Google Maps에서 확인하세요.</div>`;
}
function actualMoney(b){return `<div class="money actual-money" data-testid="actual-krw">${b.unconfirmedKrw?'확인된 합계 ':''}${fmt(b.actualKrw,2)}원<small>입력 당시·확정 원화 · NT$${fmt(b.actual,2)}</small>${b.unconfirmedKrw?`<small class="err">원화 미확정 ${b.unconfirmedKrw}건 제외</small>`:''}<small class="current-fx">현재 환율 참고 ${fmt(krw(b.actual))}원</small></div>`;}
function expenseMoney(x){const fixed=C.expenseKRW(x);return `<div class="money expense-fixed" data-expense-id="${esc(x.id)}">${fixed===null?'원화 미확정':fmt(fixed,2)+'원'}<small>${Number.isFinite(x.confirmedKrw)||x.currency==='KRW'?'확정 원화':'입력 당시 원화'} · NT$${fmt(x.twd,2)}</small><small class="current-fx">현재 환율 참고 ${fmt(krw(x.twd))}원</small></div>`;}
function moneyView(){const b=C.budget(state.trip,state.settings,state.expenses),unknown=state.trip.items.filter(x=>x.routeStale&&C.included(x)).length;
 return `<div class="section-title" style="margin-top:0"><h2>여행 예산</h2><button class="btn primary" data-action="expense">지출 추가</button></div><div class="card"><div class="mini-label">전체 예상 · 항공·숙소 제외</div>${money(b.planned,true)}<div class="grid2" style="margin-top:16px"><div><span class="mini-label">실제 기록 지출</span>${actualMoney(b)}</div><div><span class="mini-label">남은 예산 · 현재환산</span>${money(b.remaining)}</div></div></div>${unknown?`<div class="notice warn" style="margin-top:12px">변경된 이동 ${unknown}건의 요금은 아직 미확정이라 예산에서 제외했습니다.</div>`:''}<div class="grid2" style="margin-top:12px"><div class="card"><span class="mini-label">현금 잔액</span>${state.settings.cashOpening===null?'<p class="small">초기 현금을 입력하세요.</p>':money(b.cashRemaining)}<button class="btn smallbtn" data-action="cash">현금 설정</button></div><div class="card"><span class="mini-label">권장 준비 현금</span>${money(b.cashRecommended)}<p class="small">위스키·쇼핑 예산 기준</p></div></div><div class="notice" style="margin-top:12px">실제 지출은 직접 입력한 내역만 합산합니다. 카드·은행과 자동 연결되지 않으며 실제 지출 원화는 입력 당시 환산 또는 확정 결제액으로 고정합니다. 현재 환율 환산은 별도 참고값입니다.</div><button class="btn full" data-action="budget-settings">위스키·선물 예산 변경</button>
 <div class="section-title"><h3>날짜별 예상</h3></div><div class="card">${state.trip.days.map(d=>`<div class="row" style="padding:8px 0;border-bottom:1px solid var(--line)"><span>${esc(d.chip)} ${esc(d.dow)}</span>${money(C.dayItems(state.trip,d.id).filter(C.included).reduce((s,x)=>s+x.cost,0))}</div>`).join('')}<div class="row" style="padding-top:12px"><span class="small">위스키·선물 별도</span>${money(state.settings.whisky+state.settings.gifts)}</div></div>
 <div class="section-title"><h3>실제 지출 ${state.expenses.length}건</h3></div><div class="card">${state.expenses.length?state.expenses.slice().reverse().map(x=>`<div class="expense"><div><b>${esc(x.title)}</b><div class="small">${stamp(x.time,8,true)} · ${{cash:'현금',card:'카드',easy:'이지카드'}[x.method]}</div>${x.currency==='KRW'?`<div class="small">입력 원화 ${fmt(x.raw)}원 · 당시 환율 ${fmt(x.rateSnapshot,4)}</div>`:''}</div>${expenseMoney(x)}<button class="iconbtn" data-action="delete-expense" data-id="${esc(x.id)}" aria-label="지출 삭제">×</button></div>`).join(''):'<p class="small">아직 기록한 지출이 없어요.</p>'}</div>`;
}
function placesView(){const p=Object.entries(state.trip.places);const used=new Set(state.trip.items.filter(C.included).flatMap(x=>[x.place,x.from,x.to]).filter(Boolean));const list=p.filter(([id,v])=>(placeFilter!=='used'||used.has(id))&&(!query||(v.n+' '+(v.zh||'')+' '+(v.addr||'')).toLowerCase().includes(query.toLowerCase())));
 return `<h2>장소 모음</h2><input id="placeSearch" type="search" placeholder="한글·중국어·주소 검색" aria-label="장소 검색"><div class="filter-row"><button data-filter="all" aria-pressed="${placeFilter==='all'}">전체 장소 ${p.length}</button><button data-filter="used" aria-pressed="${placeFilter==='used'}">일정에 사용 ${used.size}</button><button data-filter="saved" aria-pressed="${placeFilter==='saved'}">원본 저장 목록</button></div><div id="placesList">${placeFilter==='saved'?`<p class="small">원본 분류·날짜·메모를 그대로 보존한 목록입니다. 편집한 일정과 자동 일치하지 않을 수 있어요.</p>${(state.trip.saved||[]).filter(s=>!query||s.join(' ').toLowerCase().includes(query.toLowerCase())).map(s=>`<div class="card place"><b>${esc(s[0])}</b><div class="small">${esc(s[1])} · ${rich(esc(s[3]))}</div><a class="btn smallbtn" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(s[0]+' Taipei')}" target="_blank" rel="noopener noreferrer">Google Maps에서 확인</a></div>`).join('')}`:list.map(([id,p])=>`<div class="card place"><div class="row"><h3>${esc(p.n)}</h3>${used.has(id)?'<span class="pill good">일정</span>':''}</div><div class="small">${esc(p.zh||'')}<br>${esc(p.addr||'주소 미기재 · 지도에서 확인')}</div><div class="actions"><button class="btn" data-action="place-info" data-place="${esc(id)}">장소 정보</button><button class="btn" data-action="place-route" data-place="${esc(id)}">길찾기</button><button class="btn" data-action="add-place" data-place="${esc(id)}">일정에 추가</button></div></div>`).join('')||'<p class="small">검색 결과가 없습니다.</p>'}</div>`;
}
function moreView(){
 if(morePage==='prep')return prepView();
 if(morePage==='guide'||morePage==='eats')return `<button class="btn" data-action="more-back">← 더보기</button>${sourceNote()}<div class="rich" style="margin-top:14px">${rich(morePage==='guide'?state.trip.guideHTML:state.trip.eatsHTML)}</div>`;
 if(morePage==='logs')return `<button class="btn" data-action="more-back">← 더보기</button><h2 style="margin-top:16px">변경 기록</h2><div class="card">${state.logs.map(x=>`<p class="small">${stamp(x.time,9,true)} 한국 · ${esc(x.message)}</p>`).join('')||'변경 기록이 없습니다.'}</div>`;
 return `<h2>여행 도구</h2><button class="btn primary full" data-action="conversation">여행 회화 · 중국어 / 영어</button><div class="stack">${[['prep','준비·예약 체크리스트','예약 확인과 출발 준비'],['guide','여행 가이드·중국어','원본 가이드·긴급 연락처'],['eats','배달 추천','원본 우버이츠 자료'],['logs','변경 기록','자동 조정과 직접 수정 이력']].map(([k,n,s])=>`<button class="card row" data-action="more-page" data-page="${k}" style="text-align:left"><span><b>${n}</b><small class="small" style="display:block">${s}</small></span><span>›</span></button>`).join('')}<button class="card row" data-action="settings"><b>설정·백업·앱 설치</b><span>›</span></button></div><div class="notice" style="margin-top:16px"><b>저장 방식</b><br>일정과 지출은 이 브라우저의 기기 저장소에만 보관합니다. 다른 휴대폰과 자동 동기화되지 않아요. 사이트 데이터를 지우기 전에 백업하세요.</div><div class="small">v${VERSION} · 광고·분석 추적 없음 · 자동 위치 수집 없음</div>`;
}
function prepView(){const a=state.trip.prep||[],n=a.filter(x=>state.prep[x.id]).length;return `<button class="btn" data-action="more-back">← 더보기</button><h2 style="margin-top:16px">준비·예약</h2><div class="card"><b>${n} / ${a.length} 확인 완료</b><div class="progress"><i style="width:${n/Math.max(1,a.length)*100}%"></i></div></div><div class="notice" style="margin-top:12px">원본의 ‘예약 완료’ 문구와 체크리스트 확인 상태는 별개입니다. 실제 예약 확인서를 보고 체크하세요.</div><div class="card">${a.map(p=>`<label class="check"><input type="checkbox" data-prep="${esc(p.id)}" ${state.prep[p.id]?'checked':''}><span><b>${esc(p.t)}</b><small>${rich(esc(p.w))}</small>${p.l?`<a href="${esc(/^https?:\/\//.test(p.l[1])?p.l[1]:'#')}" target="_blank" rel="noopener noreferrer">${esc(p.l[0])}</a>`:''}</span></label>`).join('')}</div><button class="btn danger" style="margin-top:12px" data-action="prep-reset">체크 초기화</button>`;}
/* ---------- Rates: daily provider quote, last successful quote offline ---------- */
function rateDescription(){
 if(state.settings.rateMode==='manual')return '수동 환율 · 자동 갱신 일시 중지';
 if(!state.fx)return fxBusy?'최신 환율 조회 중 · 임시 기준 43원':'임시 기준 43원 · 최신 환율 미확인';
 const stale=Date.now()-state.fx.quotedAt>48*3600000;
 return (navigator.onLine?(fxError?'조회 실패 · 저장값':'최신 일일 기준'):'오프라인 · 저장값')+' · '+quoteStamp(state.fx.quotedAt)+' 한국'+(stale?' · 오래된 환율':'');
}
function updateTop(){
 $('#fxRate').textContent=`NT$1 ≈ ${fmt(appliedRate(),4)}원${state.settings.fee?' · 여유 '+state.settings.fee+'%':''}`;
 $('#fxStatus').textContent=rateDescription();
 $('#onlineState').textContent=navigator.onLine?'● 네트워크 연결':'○ 오프라인';$('#onlineState').classList.toggle('bad',!navigator.onLine);
 $('#cacheBtn').textContent=cacheReady?'오프라인 저장 완료':'오프라인 준비 확인';
}
async function refreshRate(force=false){
 if(!navigator.onLine){fxError='오프라인';updateTop();return;}
 if(state.settings.rateMode==='manual'||fxBusy)return;
 const now=Date.now();if(force&&now-fxAttempt<60000){toast('잦은 조회를 막기 위해 1분 후 다시 확인해 주세요.');return;}
 if(!force&&(now-fxAttempt<15*60000||state.fx&&(now<state.fx.nextAt||now-state.fx.fetchedAt<3600000)))return;
 fxBusy=true;fxError='';fxAttempt=now;updateTop();const abort=new AbortController(),timeout=setTimeout(()=>abort.abort(),8000);
 try{
  const r=await fetch('https://open.er-api.com/v6/latest/TWD',{signal:abort.signal,cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('HTTP '+r.status);
  const j=await r.json(),v=j.rates?.KRW,q=j.time_last_update_unix*1000;
  if(j.result!=='success'||j.base_code!=='TWD'||!Number.isFinite(v)||v<=0||v>1000||!Number.isFinite(q)||q>Date.now()+C.DAY)throw Error('환율 응답 검증 실패');
  if(state.fx&&q<state.fx.quotedAt)throw Error('기존보다 오래된 환율 응답');
  state.fx={rate:v,quotedAt:q,fetchedAt:Date.now(),nextAt:Number.isFinite(j.time_next_update_unix)?j.time_next_update_unix*1000:Date.now()+C.DAY,source:'ExchangeRate-API'};persist();
  if(force)toast('제공처의 최신 일일 환율로 확인했어요.');
 }catch(e){fxError=e.message;if(force)toast('최신 조회 실패: 마지막 성공 환율을 유지합니다.');}
 finally{clearTimeout(timeout);fxBusy=false;updateTop();if(!$('#sheet').open)render(false);else if($('#fxAmount'))updateConversion();}
}
function calculator(){showSheet('환율 계산기',`<p class="small" id="fxDetail">${esc(rateDescription())}</p><div class="grid2"><label class="field">입력 통화<select id="fxCurrency"><option value="TWD">대만달러 NT$ → 원</option><option value="KRW">원 → 대만달러 NT$</option></select></label><label class="field">금액<input id="fxAmount" class="big-input" inputmode="decimal" value="1000" autocomplete="off"></label></div><div class="convert-output" id="fxResult" aria-live="polite"></div><div class="quick">${[100,500,1000,2000].map(n=>`<button class="btn" data-quick="${n}">${fmt(n)}</button>`).join('')}</div><p class="small">은행 매매·카드 결제 확정환율이 아닌 참고 환율입니다. 무료 제공처는 하루 단위로 갱신합니다.</p><div class="actions"><button class="btn primary" data-action="refresh-rate">최신 환율 확인</button><button class="btn" data-action="rate-settings">수동 환율·여유율</button></div><p class="small" style="margin-top:14px">${state.fx?'제공처 기준: '+quoteStamp(state.fx.quotedAt)+' 한국<br>마지막 성공 조회: '+quoteStamp(state.fx.fetchedAt)+' 한국<br>':''}<a href="https://www.exchangerate-api.com" target="_blank" rel="noopener noreferrer">Rates By Exchange Rate API</a></p>`);$('#fxAmount').oninput=updateConversion;$('#fxCurrency').onchange=updateConversion;$$('[data-quick]').forEach(b=>b.onclick=()=>{$('#fxAmount').value=b.dataset.quick;updateConversion();feedback()});updateConversion();}
function updateConversion(){if(!$('#fxAmount'))return;const raw=$('#fxAmount').value.trim(),v=Number(raw.replaceAll(',','')),mode=$('#fxCurrency').value;$('#fxResult').textContent=!raw||!Number.isFinite(v)||v<0?'금액을 입력하세요.':mode==='TWD'?`약 ${fmt(v*appliedRate())}원`:`약 NT$${fmt(v/appliedRate(),2)}`;$('#fxDetail').textContent=rateDescription();}
function rateSettings(){showSheet('환율 설정',`<form id="rateForm"><label class="field">환율 기준<select name="mode"><option value="auto" ${state.settings.rateMode==='auto'?'selected':''}>온라인 최신 일일 환율</option><option value="manual" ${state.settings.rateMode==='manual'?'selected':''}>내가 입력한 환율</option></select></label><label class="field">수동 기준 · NT$1당 원화<input name="manual" type="number" min="0.001" max="1000" step="0.001" inputmode="decimal" value="${state.settings.manualRate}" required></label><label class="field">카드·환전 비용 여유율 (%)<input name="fee" type="number" min="0" max="20" step="0.1" inputmode="decimal" value="${state.settings.fee}" required><small>기본값 0%. 실제 수수료와 다를 수 있으며 본인이 정하는 예산 여유율입니다.</small></label><p class="err" id="formError"></p><button class="btn primary full">저장</button></form>`);$('#rateForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),manual=Number(f.get('manual')),fee=Number(f.get('fee'));if(!(manual>0&&manual<=1000&&fee>=0&&fee<=20))return formError('환율과 여유율을 확인하세요.');mutate(()=>{state.settings.rateMode=f.get('mode');state.settings.manualRate=manual;state.settings.fee=fee},'환율 설정을 저장했어요.');closeSheet(true,true);if(state.settings.rateMode==='auto'){fxAttempt=0;refreshRate(true)}};}
function formError(msg){if($('#formError'))$('#formError').textContent=msg;else toast(msg);}
/* ---------- Editable itinerary and protected schedule ---------- */
function placeOptions(current,emptyLabel='장소 없음'){return `<option value="">${emptyLabel}</option><option value="__new__">＋ 새 장소 직접 입력</option>`+Object.entries(state.trip.places).map(([id,p])=>`<option value="${esc(id)}" ${id===current?'selected':''}>${esc(p.n)}</option>`).join('');}
function editor(id=null,placeId=null){
 C.bindRouteAnchors(state.trip);const x=id?getItem(id):null,d=selectedDay(),tz=x?.tz??d.tz,endTz=x?.endTz??tz,start=x?.start??C.parseLocal(d.date+'T12:00',tz),end=x?.end??start+30*C.MIN;
 showSheet(x?'일정 편집':'일정 추가',`<form id="editForm"><label class="field">제목<input name="title" value="${esc(x?.title||state.trip.places[placeId]?.n||'')}" maxlength="300" required></label><div class="grid2"><label class="field">종류<select name="kind" id="editKind">${x?.k!=='m'?'<option value="s" selected>방문·식사·휴식</option>':''}${x?.k==='m'?'<option value="m" selected>이동 (경로 자동 연결)</option>':''}</select></label><label class="field">날짜 묶음<select name="day">${state.trip.days.map(a=>`<option value="${esc(a.id)}" ${a.id===(x?.dayId||d.id)?'selected':''}>${esc(a.chip)} ${esc(a.dow)}</option>`).join('')}</select></label></div><div class="grid2"><label class="field">시작<input name="start" type="datetime-local" value="${C.localInput(start,tz)}" required><select name="startTz"><option value="8" ${tz===8?'selected':''}>대만 시각</option><option value="9" ${tz===9?'selected':''}>한국 시각</option></select></label><label class="field">종료<input name="end" type="datetime-local" value="${C.localInput(end,endTz)}" required><select name="endTz"><option value="8" ${endTz===8?'selected':''}>대만 시각</option><option value="9" ${endTz===9?'selected':''}>한국 시각</option></select></label></div><label class="field">장소 / 이동의 도착지<select name="place" id="editPlace">${placeOptions(x?.place||x?.to||placeId)}</select></label><div id="newPlaceFields" hidden><label class="field">새 장소 이름<input name="newName" maxlength="300"></label><label class="field">중국어 이름 또는 주소<input name="newAddress" maxlength="500"><small>입력한 이름·주소로 Google Maps를 엽니다. 임의 좌표를 만들지 않습니다.</small></label></div><div id="moveFields" ${x?.k==='m'?'':'hidden'}><label class="field">출발지<select name="from">${placeOptions(x?.from,'출발지 직접 선택')}</select></label><label class="field">이동수단<select name="travel">${[['transit','대중교통'],['walking','도보'],['driving','차량·우버']].map(([a,b])=>`<option value="${a}" ${x?.travel===a?'selected':''}>${b}</option>`).join('')}</select></label></div><div class="grid2"><label class="field">예상 비용 NT$<input name="cost" type="number" inputmode="decimal" min="0" max="10000000" step="0.01" value="${x?.cost||0}" required><small id="editCostKrw">${inlineMoney(x?.cost||0)}</small></label><label class="field">결제수단<select name="pay">${[...new Set(['카드','현금','이지카드','우버(카드)','결제완료','-',x?.pay].filter(Boolean))].map(v=>`<option ${x?.pay===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label></div><label class="check"><input name="fixed" type="checkbox" ${x?.fixed?'checked':''}><span>고정 일정으로 보호<small>항공·예약 등. 자동 조정에서는 시간·순서를 바꾸지 않습니다.</small></span></label><label class="check"><input name="buffer" type="checkbox" ${x?.buffer?'checked':''}><span>줄일 수 있는 휴식 버퍼<small>최소 ${state.settings.minRest}분 보장. 이동시간은 줄이지 않습니다.</small></span></label>${x?.routeStale?'<label class="check"><input name="routeConfirmed" type="checkbox"><span>Google Maps에서 변경 경로의 시간·요금을 확인하고 위 입력값에 반영했습니다.</span></label>':''}<label class="field">내 메모<textarea name="notes" maxlength="5000">${esc(x?.notes||'')}</textarea></label>${x?.fixed?'<div class="notice warn">이 화면에서 고정시간을 직접 바꿔도 식당 예약·항공권 자체는 변경되지 않습니다.</div>':''}<p class="err" id="formError"></p><button class="btn primary full">${x?'변경 저장':'일정 추가'}</button></form>`);
 $('#editPlace').onchange=e=>{$('#newPlaceFields').hidden=e.target.value!=='__new__';};$('#editKind').onchange=e=>{$('#moveFields').hidden=e.target.value!=='m';};$('#editForm [name=cost]').oninput=e=>{$('#editCostKrw').textContent='약 '+fmt(krw(Number(e.target.value)||0))+'원';};
 $('#editForm').onsubmit=e=>{e.preventDefault();try{
  const f=new FormData(e.target),s=C.parseLocal(f.get('start'),Number(f.get('startTz'))),end=C.parseLocal(f.get('end'),Number(f.get('endTz'))),cost=Number(f.get('cost'));
  if(end<s||(end===s&&x?.timeStatus!=='milestone'&&!x?.routeStale)||end-s>7*C.DAY)throw Error('종료는 시작 이후로 입력하세요. 자정을 넘기면 종료 날짜도 다음 날로 바꿔주세요.');
  if(!f.get('title').trim()||!Number.isFinite(cost)||cost<0||cost>1e7)throw Error('제목과 비용을 확인하세요.');
  let place=f.get('place'),newPlace=null;if(place==='__new__'){if(!f.get('newName').trim())throw Error('새 장소 이름을 입력하세요.');place='p-'+C.id();newPlace={n:f.get('newName').trim(),zh:'',addr:f.get('newAddress').trim()};}
  const kind=f.get('kind'),from=f.get('from');if(x?.k==='m'&&(kind!=='m'||f.get('day')!==x.dayId))throw Error('이동카드 자체의 종류·날짜는 변경하지 않습니다. 방문 일정을 옮기세요.');if(kind==='m'&&(!place||!from||from==='__new__'))throw Error('이동의 출발지와 도착지를 선택하세요. 새 출발지는 먼저 장소가 있는 일정을 추가해 등록하세요.');
  if(x&&f.get('day')!==x.dayId&&x.status!=='pending')throw Error('진행 전 일정만 날짜를 이동할 수 있습니다.');
  if(x?.routeStale&&f.has('routeConfirmed')&&end<=s)throw Error('확인한 이동시간을 0보다 크게 입력하세요.');
  const targetDay=state.trip.days.find(d=>d.id===f.get('day'));if(!targetDay)throw Error('날짜를 선택하세요.');
  if(C.localInput(s,Number(f.get('startTz'))).slice(0,10)!==targetDay.date)throw Error('시작 날짜와 날짜 묶음을 일치시켜 주세요.');
  mutate(()=>{
   if(newPlace)state.trip.places[place]=newPlace;
   const old=x?C.clone(x):null;const samePlace=old?.place===(place||null);const it=x||{id:'u-'+C.id(),k:kind,dayId:f.get('day'),status:'pending',actualStart:null,actualEnd:null,body:'',tags:[]};
   Object.assign(it,{title:f.get('title').trim(),start:s,end,tz:Number(f.get('startTz')),endTz:Number(f.get('endTz')),dayId:f.get('day'),k:kind,place:kind==='s'?(place||null):null,from:kind==='m'?from:undefined,to:kind==='m'?place:undefined,travel:f.get('travel')||'transit',cost,pay:f.get('pay'),fixed:f.has('fixed'),buffer:f.has('buffer')&&kind==='s'&&!f.has('fixed'),notes:f.get('notes').trim()});
   if(old&&old.k==='s'&&(!samePlace||kind!=='s')){it.body='장소가 변경되었습니다. 이전 장소의 안내는 원본 복원 데이터에 보존됩니다.';it.kv=[];it.tip='';it.sub='';it.tags=[];}
   if(it.routeStale&&f.has('routeConfirmed')){it.routeStale=false;it.timeStatus='user-confirmed';it.fareStatus='user-confirmed';it.durationMinutes=(end-s)/C.MIN;it.steps=['사용자가 Google Maps에서 확인한 이동시간·요금입니다.'];}
   if(old?.k==='m'&&(old.from!==it.from||old.to!==it.to||old.travel!==it.travel)){it.routeStale=true;it.timeStatus='unconfirmed';it.fareStatus='unconfirmed';it.durationMinutes=null;it.steps=['경로 변경 후 Google Maps에서 새 이동시간·요금을 확인하세요.'];it.cost=0;it.pay='미확정';}
   if(!x){it.originalStart=s;it.originalEnd=end;state.trip.items.push(it);}
   state.trip.items.sort((a,b)=>state.trip.days.findIndex(d=>d.id===a.dayId)-state.trip.days.findIndex(d=>d.id===b.dayId)||a.start-b.start);
   if(it.k==='s'||old?.k==='s'){if(old)C.rebuildDayRoutes(state.trip,old.dayId);if(!old||old.dayId!==it.dayId)C.rebuildDayRoutes(state.trip,it.dayId);}
   curDay=it.dayId;openCards.add(it.id);
  },x?'일정을 수정했어요.':'새 일정을 추가했어요.');closeSheet(true,true);
 }catch(err){formError(err.message);}};
}
function reveal(id){const x=getItem(id);if(!x)return;rememberScroll();tab='plan';curDay=x.dayId;openCards.add(id);render();requestAnimationFrame(()=>{const el=document.getElementById('event-'+id);el?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});el?.classList.add('glow');});}
function markItem(id,action){const x=getItem(id);if(!x)return;
 if(action==='start'){const running=state.trip.items.find(i=>i.status==='running'&&i.id!==id);if(running){confirmAction('진행 중인 일정이 있어요','현재 진행 기록을 중지하고 새 일정을 시작합니다. 기존 일정은 완료가 아니라 미완료 상태로 돌아갑니다.',()=>{snapshot();running.status='pending';running.actualStart=null;startIt(id);});return;}snapshot();startIt(id);return;}
 if(action==='done'){
  snapshot();const now=Date.now();x.status='done';x.actualEnd=now;log(x.title+' 완료 기록');
  const delay=now-x.end;if(delay>5*C.MIN&&delay<6*3600000&&!C.protectedItem(x)){const p=C.proposeDelay(state.trip,id,now,state.settings);if(!p.conflict&&state.settings.autoDelay){state.trip=C.applyDelay(state.trip,p);log('완료 기록 기준 이후 일정 '+p.delay+'분 조정');}else delayProposal=p;}
  persist();render();toast('완료로 기록했어요.',true);return;
 }
 if(action==='cancel-item'){confirmAction('앱에서 취소 상태로 표시할까요?','실제 항공·식당 예약은 취소되지 않습니다. 예약처에 별도로 연락하세요.',()=>mutate(()=>{x.status='cancelled';x.actualStart=null;x.actualEnd=null;C.rebuildDayRoutes(state.trip,x.dayId)},'취소 상태로 표시했어요. 실제 예약은 별도 확인하세요.'));return;}
 if(action==='skip'){
  const apply=()=>mutate(()=>{x.status='skipped';x.actualStart=null;C.repairRoutes(state.trip,x.dayId,id)},'일정을 건너뛰었어요. 연결 경로도 확인하세요.');
  if(C.protectedItem(x))confirmAction('고정 일정을 건너뛸까요?','앱 표시만 건너뛰며 실제 식당·항공 예약은 취소되지 않습니다.',apply);else apply();return;
 }
 if(action==='unmark'){mutate(()=>{x.status='pending';x.actualStart=null;x.actualEnd=null;C.repairRoutes(state.trip,x.dayId,id)},'일정 상태를 되돌렸어요. 변경 동선은 지도에서 확인하세요.');return;}
}
function startIt(id){const x=getItem(id),now=Date.now();x.status='running';x.actualStart=now;log(x.title+' 시작 기록');
 const lateness=now-x.start;if(lateness>5*C.MIN&&lateness<6*3600000&&!C.protectedItem(x)){const p=C.proposeDelay(state.trip,id,now+C.duration(x)*C.MIN,state.settings);if(!p.conflict&&state.settings.autoDelay){state.trip=C.applyDelay(state.trip,p);log('시작 기록 기준 지연 '+p.delay+'분 자동 반영');}else delayProposal=p;}
 persist();render();toast('시작 시각을 기록했어요.',true);
}
function delaySheet(id){const x=getItem(id);if(!x)return;showSheet('일정 지연 조정',`<b>${esc(x.title)}</b><p class="small" style="margin-top:8px">고정 예약은 보호하고, 빈 시간·휴식 버퍼를 먼저 사용합니다. 이동시간은 줄이지 않아요.</p><div class="actions">${[15,30,60].map(n=>`<button class="btn" data-delay-min="${n}">+${n}분</button>`).join('')}</div><p class="source-note">체크가 안 된 사실만으로 실제 지연을 판단하지 않습니다. 아래 조정은 직접 선택한 지연분을 기준으로 계산합니다.</p>`);$$('[data-delay-min]').forEach(b=>b.onclick=()=>{delayProposal=C.proposeDelay(state.trip,id,x.end+Number(b.dataset.delayMin)*C.MIN,state.settings);reviewDelay();});}
function reviewDelay(){if(!delayProposal){toast('검토할 지연 조정안이 없습니다.');return;}const p=delayProposal;
 showSheet('지연 조정안',`${p.conflict?`<div class="notice warn"><b>자동 적용하지 않았습니다.</b><br>${esc(p.conflict.reason)}${p.conflict.title?'<br>'+esc(p.conflict.title):''}${p.conflict.minutes?' · 여유 '+p.conflict.minutes+'분 부족':''}</div>`:`<div class="notice">${p.delay}분 지연 반영 · 고정 일정은 유지합니다.</div>`}<div class="change-list">${p.changes.map(x=>`<div><b>${esc(x.title)}</b><br>${stamp(x.oldStart,8,true)}–${stamp(x.oldEnd,8)} → ${stamp(x.start,8,true)}–${stamp(x.end,8)}<span class="small"> (대만 환산)</span></div>`).join('')||'변경 가능한 일정이 없습니다.'}</div><div class="actions" style="margin-top:16px">${!p.conflict&&p.changes.length?'<button class="btn primary" id="applyDelay">이 조정 적용</button>':''}${p.conflict?.id&&getItem(p.conflict.id)?`<button class="btn" data-action="route" data-id="${esc(p.conflict.id)}">고정 일정 길찾기</button>`:''}<button class="btn" data-action="dismiss-delay">닫기</button></div><p class="small" style="margin-top:12px">계산은 저장된 이동시간 기준입니다. 실제 교통·항공편 지연을 조회한 결과가 아닙니다.</p>`);
 if($('#applyDelay'))$('#applyDelay').onclick=()=>{try{mutate(()=>{state.trip=C.applyDelay(state.trip,p);delayProposal=null},'지연 조정안을 적용했어요.');closeSheet(true,true);}catch(e){delayProposal=null;closeSheet(true,true);render(false);toast(e.message);}};
}
function autoCheckDelay(){
 if(!state.trip||document.hidden||$('#sheet').open)return;
 const x=state.trip.items.find(i=>i.status==='running');if(!x||C.protectedItem(x)||!x.actualStart)return;
 const late=Date.now()-x.end;if(late<5*C.MIN||late>6*3600000)return;
 const signature=x.id+':'+Math.floor(x.end/(5*C.MIN));if(signature===lastActiveId)return;lastActiveId=signature;
 const p=C.proposeDelay(state.trip,x.id,Math.ceil(Date.now()/(5*C.MIN))*5*C.MIN,state.settings);
 if(!p.changes.length&&!p.conflict)return;
 if(p.conflict||!state.settings.autoDelay){delayProposal=p;log(p.conflict?'지연 조정 보류: '+p.conflict.reason:'지연 조정 제안 생성 (아직 미적용)');persist();render(false);toast(p.conflict?'고정 일정 또는 변경 경로 확인이 필요해요.':'지연 조정안을 확인한 뒤 적용하세요.');}
 else{snapshot();state.trip=C.applyDelay(state.trip,p);delayProposal=null;log('진행 기록 기준 '+p.delay+'분 자동 조정');persist();render(false);toast('진행 중인 일정의 지연을 반영했어요.',true);}
}
/* ---------- Google Maps: no API key, explicit origin and destination ---------- */
function routeSheet(id=null,placeId=null){const x=id?getItem(id):null;if(placeId==='lounge'||TaipeiUX.isIndoorTransfer(x)){placeSheet('lounge',id);return;}const r=x?C.routeFor(state.trip,x):{from:null,to:placeId,mode:'transit'};
 if(!r.to){toast('도착지 정보가 없어요. 일정 편집에서 장소를 지정하세요.');return;}
 showSheet('Google Maps 길찾기',`<p class="small">${navigator.onLine?'출발지·도착지를 입력한 Google Maps를 엽니다.':'오프라인입니다. 지도 서비스와 대중교통 경로에는 연결이 필요할 수 있습니다.'}</p><label class="field">출발<select id="routeFrom"><option value="">Google Maps의 현재 위치</option>${Object.entries(state.trip.places).map(([id,p])=>`<option value="${esc(id)}" ${id===r.from?'selected':''}>${esc(p.n)}</option>`).join('')}</select></label><label class="field">도착<select id="routeTo">${Object.entries(state.trip.places).map(([id,p])=>`<option value="${esc(id)}" ${id===r.to?'selected':''}>${esc(p.n)}</option>`).join('')}</select></label><label class="field">이동수단<select id="routeMode">${[['transit','대중교통'],['walking','도보'],['driving','차량·우버']].map(([v,n])=>`<option value="${v}" ${v===r.mode?'selected':''}>${n}</option>`).join('')}</select></label><a class="btn primary full" id="openMaps" target="_blank" rel="noopener noreferrer">Google Maps 열기</a><p class="small" style="margin-top:12px">‘현재 위치’를 고르면 위치 권한은 Google Maps가 처리합니다. 이 수첩은 위치를 수집하지 않습니다. 지도에서 바꾼 경로는 수첩으로 자동 회신되지 않아요.</p>`);
 const set=()=>{try{$('#openMaps').href=C.mapsURL(state.trip.places,$('#routeFrom').value||null,$('#routeTo').value,$('#routeMode').value)}catch(e){toast(e.message)}};['#routeFrom','#routeTo','#routeMode'].forEach(s=>$(s).onchange=set);set();
}
function dayRoutes(){const stops=C.dayItems(state.trip,curDay).filter(x=>x.k==='s'&&x.place&&x.place!=='lounge'&&!x.isFlight&&C.included(x));const seq=stops.filter((x,i)=>i===0||x.place!==stops[i-1].place);
 showSheet('하루 동선',`<p class="small">공항 안의 라운지는 외부 지도 경로에서 제외했어요. 대중교통은 구간별로 여세요. 여러 경유지 경로는 도보·차량으로만 만들며 모바일 호환성을 위해 최대 3곳씩 나눕니다.</p><div class="stack">${seq.slice(1).map((x,i)=>`<a class="btn" style="justify-content:flex-start;text-align:left" href="${esc(C.mapsURL(state.trip.places,seq[i].place,x.place,'transit'))}" target="_blank" rel="noopener noreferrer">${esc(state.trip.places[seq[i].place].n)} → ${esc(state.trip.places[x.place].n)}</a>`).join('')||'<p class="small">장소가 있는 일정이 2개 이상 필요합니다.</p>'}</div>${seq.length>2?`<div class="sep"></div><label class="field">여러 장소 함께 보기<select id="multiMode"><option value="driving">차량 경로</option><option value="walking">도보 경로</option></select></label><div id="multiLinks" class="stack"></div>`:''}`);
 if($('#multiMode')){const multi=()=>{let h='';for(let i=0;i<seq.length-1;i+=4){const group=seq.slice(i,i+5);h+=`<a class="btn" href="${esc(C.mapsURL(state.trip.places,group[0].place,group.at(-1).place,$('#multiMode').value,group.slice(1,-1).map(x=>x.place)))}" target="_blank" rel="noopener noreferrer">${i+1}~${i+group.length}번째 장소 · ${group.length-2}개 경유</a>`;}$('#multiLinks').innerHTML=h;};$('#multiMode').onchange=multi;multi();}
}
const phraseCategories={all:'전체',hotel:'호텔',restaurant:'식당',shopping:'쇼핑',move:'이동·기타'};
let phraseQuery='',phraseCategory='all';
async function copyTravelText(value){try{await navigator.clipboard.writeText(value);toast('복사했어요.');}catch(e){toast('복사가 제한돼요. 큰 글씨를 길게 눌러 복사해 주세요.');}}
function placeSheet(placeId,itemId=null){const p=state.trip?.places[placeId];if(!p)return;const item=itemId?getItem(itemId):null,eligible=TaipeiUX.resolveDriver(placeId,p,item).eligible;
 showSheet('장소 정보',`<div class="communication"><p class="communication-ko">${esc(p.n)}</p><span class="mini-label">현지 장소명</span><div class="place-zh" lang="zh-Hant">${esc(p.zh||p.n)}</div><span class="mini-label">주소 · 현지 원문</span><p class="place-address" lang="zh-Hant">${esc(p.addr||'주소가 등록되지 않았어요. 지도에서 확인해 주세요.')}</p>${placeId==='lounge'?'<p class="notice">공항 안에 있는 장소예요. 항공편 터미널과 라운지 위치를 예약 안내에서 확인하고, 출국 수속 후 안내 표지를 따라가세요.</p>':''}<div class="actions">${p.addr?'<button class="btn" id="copyPlace">주소 복사</button>':''}${eligible?`<button class="btn primary" id="openTaxi">택시 기사님께 보여주기</button>`:''}<button class="btn" data-action="conversation">여행 회화 · 중국어 / 영어</button></div></div>`);
 if($('#copyPlace'))$('#copyPlace').onclick=()=>copyTravelText([p.zh||p.n,p.addr].join('\n'));if($('#openTaxi'))$('#openTaxi').onclick=()=>driver(placeId,itemId);
}
function driver(placeId,itemId=null){const p=state.trip?.places[placeId];if(!p)return;const item=itemId?getItem(itemId):null;if(!TaipeiUX.resolveDriver(placeId,p,item).eligible){placeSheet(placeId,itemId);return;}
 showSheet('택시 목적지',`<div class="communication"><p class="communication-ko">목적지: ${esc(p.n)}</p><div class="driver-name" lang="zh-Hant">${esc(p.zh||p.n)}</div><span class="mini-label">주소 · 기사님께 보여주세요</span><div class="driver-address" lang="zh-Hant">${esc(p.addr)}</div><div class="driver-phrase" lang="zh-Hant">請載我到這裡，謝謝。</div><p class="communication-ko">여기로 가 주세요. 감사합니다.</p><div class="actions"><button class="btn primary" id="copyTaxi">목적지·주소 복사</button><button class="btn" id="taxiInfo">장소 정보</button></div></div>`);
 $('#copyTaxi').onclick=()=>copyTravelText([p.zh||p.n,p.addr,'請載我到這裡，謝謝。'].join('\n'));$('#taxiInfo').onclick=()=>placeSheet(placeId,itemId);
}
const conversationGroups=TaipeiUX.CONVERSATION_GROUPS;
let conversationLanguage='zh',conversationCategory='',conversationSubgroup='',conversationQuery='',conversationPhraseId='';
function conversationRows(){return TRAVEL_PHRASES.slice();}
function conversationHeader(){return `<div class="conversation-languages" role="group" aria-label="표현을 보여줄 언어"><button class="btn ${conversationLanguage==='zh'?'primary':''}" id="languageZh" aria-pressed="${conversationLanguage==='zh'}">중국어 · 번체</button><button class="btn ${conversationLanguage==='en'?'primary':''}" id="languageEn" aria-pressed="${conversationLanguage==='en'}">영어</button></div>`;}
function bindConversationLanguage(){for(const [id,lang] of [['languageZh','zh'],['languageEn','en']]){const b=$('#'+id);if(b)b.onclick=()=>{if(conversationLanguage===lang)return;conversationLanguage=lang;conversationPhraseId?conversationPhrase(conversationPhraseId):conversationView();$('#'+id)?.focus();};}}
function conversationHome(lang='zh'){conversationLanguage=lang==='en'?'en':'zh';conversationCategory='';conversationSubgroup='';conversationQuery='';conversationView();}
function englishView(){conversationHome('en');}
function conversationContext(){const group=conversationGroups[conversationCategory];return `<p class="conversation-context">${esc(group?.[0]||'여행 회화')}${conversationSubgroup?' · '+esc(conversationSubgroup):''}</p>`;}
function conversationView(){
 conversationPhraseId='';
 const rows=conversationRows(),group=conversationGroups[conversationCategory];
 if(!group){showSheet('여행 회화',`<p class="small">상황과 세부 상황을 고른 뒤, 같은 표현을 중국어 또는 영어로 보여주세요.</p><div class="conversation-grid">${Object.entries(conversationGroups).map(([id,[name,desc]])=>`<button class="conversation-card" data-conversation-category="${esc(id)}"><b>${esc(name)}</b><span>${esc(desc)}</span><small>${rows.filter(x=>x.category===id).length}개 표현 · 중국어 / 영어</small></button>`).join('')}</div>`);$$('[data-conversation-category]').forEach(b=>b.onclick=()=>{conversationCategory=b.dataset.conversationCategory;conversationSubgroup='';conversationQuery='';conversationView();});return;}
 const selected=rows.filter(x=>x.category===conversationCategory),subgroups=TaipeiUX.phraseSubgroups(conversationCategory);
 if(!subgroups.includes(conversationSubgroup)){
  conversationSubgroup='';conversationQuery='';
  showSheet(group[0],`<button class="btn" id="backConversation">← 상황 선택</button><p class="small conversation-instruction">어떤 상황인가요? 세부 상황을 골라주세요.</p><div class="conversation-grid">${subgroups.map(s=>`<button class="conversation-card" data-conversation-subgroup="${esc(s)}"><b>${esc(s)}</b><small>${selected.filter(x=>x.subgroup===s).length}개 표현 · 중국어 / 영어</small></button>`).join('')}</div>`);
  $('#backConversation').onclick=()=>conversationHome(conversationLanguage);
  $$('[data-conversation-subgroup]').forEach(b=>b.onclick=()=>{conversationSubgroup=b.dataset.conversationSubgroup;conversationQuery='';conversationView();});return;
 }
 showSheet(conversationSubgroup,`<button class="btn" id="backConversationSubgroups">← ${esc(group[0])} · 세부 상황</button>${conversationContext()}${conversationHeader()}<label class="field">이 상황에서 표현 찾기<input id="conversationSearch" type="search" placeholder="한국어·중국어·영어로 검색" value="${esc(conversationQuery)}"></label><p class="small" id="conversationCount" role="status" aria-live="polite"></p><div id="conversationList" class="phrase-list"></div>`);
 bindConversationLanguage();$('#backConversationSubgroups').onclick=()=>{conversationSubgroup='';conversationQuery='';conversationView();};
 const draw=()=>{const matches=TaipeiUX.searchPhrases(conversationQuery,conversationCategory,conversationSubgroup),isZh=conversationLanguage==='zh';$('#conversationCount').textContent=matches.length+'개 표현';$('#conversationList').innerHTML=matches.map(x=>`<button class="phrase-item" data-conversation-phrase="${esc(x.id)}"><b>${esc(x.ko)}</b><span lang="${isZh?'zh-Hant':'en'}">${esc(isZh?x.zh:x.en)}</span><small>크게 보기 ›</small></button>`).join('')||'<p class="small">다른 단어로 찾아보세요.</p>';$$('[data-conversation-phrase]').forEach(b=>b.onclick=()=>conversationPhrase(b.dataset.conversationPhrase));markSheetClean();};
 $('#conversationSearch').oninput=e=>{conversationQuery=e.target.value;draw();};draw();
}
function conversationPhrase(id){const p=conversationRows().find(x=>x.id===id);if(!p)return;const isZh=conversationLanguage==='zh',value=isZh?p.zh:p.en;if(!value)return;
 conversationPhraseId=p.id;conversationCategory=p.category;conversationSubgroup=p.subgroup;
 showSheet('보여주기',`<button class="btn" id="backConversationList">← 표현 목록</button>${conversationContext()}${conversationHeader()}<div class="communication conversation-display" data-selected-phrase="${esc(p.id)}"><div class="phrase-large" lang="${isZh?'zh-Hant':'en'}">${esc(value)}</div><p class="communication-ko">${esc(p.ko)}</p>${isZh?`<div class="pronunciation"><b>따라 읽기</b><p>${esc(p.pronunciationKo)}</p><small lang="zh-Latn">${esc(p.pinyin)}</small></div><p class="small">한글 발음은 근사치이며 성조를 완전히 표현하지 못해요. 중국어 문장도 함께 보여주세요.</p>`:''}<div class="actions"><button class="btn primary" id="copyConversation">문장 복사</button></div></div>`);bindConversationLanguage();$('#copyConversation').onclick=()=>copyTravelText(value);$('#backConversationList').onclick=conversationView;
}
function bindGuidePhrases(){if(tab!=='more'||morePage!=='guide')return;$$('#main .zh').forEach(span=>{const source=span.textContent.replace(/\s+/g,'');const match=TRAVEL_PHRASE_ALIASES[source];if(!match)return;const b=document.createElement('button');b.className='btn guide-phrase';b.textContent=span.textContent;b.setAttribute('aria-label',span.textContent+' 크게 보기');b.onclick=()=>{conversationLanguage='zh';conversationCategory=match.category;conversationSubgroup=match.subgroup||'';conversationQuery='';match.id?conversationPhrase(match.id):conversationView();};span.replaceWith(b);});}

/* ---------- Expenses and local cash ledger ---------- */
function expenseSheet(itemId=null){const x=itemId?getItem(itemId):null;showSheet('실제 지출 기록',`<form id="expenseForm"><label class="field">내용<input name="title" maxlength="200" required value="${esc(x?.title||'')}" placeholder="예: 저녁 식사"></label><div class="grid2"><label class="field">통화<select name="currency" id="expenseCurrency"><option value="TWD">대만달러 NT$</option><option value="KRW">원화 결제액</option></select></label><label class="field">금액<input name="amount" id="expenseAmount" inputmode="decimal" type="number" min="0.01" max="100000000" step="0.01" value="${x?.cost||''}" required></label></div><p id="expenseConversion" class="money"></p><label class="field">확정 원화 결제액 · 선택<input name="confirmedKrw" type="number" min="0.01" max="1000000000000" step="0.01" inputmode="decimal" placeholder="TWD 입력 시 카드 청구액이 확정된 경우"><small>비워두면 입력 당시 환산액을 고정합니다. 원화 통화로 입력하면 입력액 자체가 확정 원화입니다.</small></label><label class="field">결제수단<select name="method"><option value="card">카드·우버</option><option value="cash" ${x?.pay==='현금'?'selected':''}>현금</option><option value="easy" ${x?.pay==='이지카드'?'selected':''}>이지카드</option></select></label><label class="field">사용 시각 · 대만 기준<input name="time" type="datetime-local" value="${C.localInput(Date.now(),8)}" required></label><p class="small">입력한 환율과 원금도 함께 저장합니다. 이지카드 충전액은 현금 잔액에 별도로 반영하고 사용액과 중복 지출로 기록하지 마세요.</p><p class="err" id="formError"></p><button class="btn primary full">지출 저장</button></form>`);
 const preview=()=>{const n=Number($('#expenseAmount').value)||0;$('#expenseConversion').textContent=$('#expenseCurrency').value==='TWD'?'약 '+fmt(krw(n))+'원':'약 NT$'+fmt(n/appliedRate(),2)};$('#expenseAmount').oninput=preview;$('#expenseCurrency').onchange=preview;preview();
 $('#expenseForm').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),raw=Number(f.get('amount')),currency=f.get('currency'),twd=currency==='TWD'?raw:raw/appliedRate();if(!(raw>0&&raw<=1e8))throw Error('0보다 큰 금액을 입력하세요.');const entry={id:C.id(),itemId,title:f.get('title').trim(),raw,currency,twd,rateSnapshot:appliedRate(),krwAtEntry:currency==='KRW'?raw:krw(raw),method:f.get('method'),time:C.parseLocal(f.get('time'),8)};if(!entry.title)throw Error('지출 내용을 입력하세요.');if(currency==='KRW')entry.confirmedKrw=raw;else if(String(f.get('confirmedKrw')||'').trim()){const confirmed=Number(f.get('confirmedKrw'));if(!Number.isFinite(confirmed)||confirmed<=0||confirmed>1e12)throw Error('확정 원화를 확인하세요.');entry.confirmedKrw=confirmed;}mutate(()=>state.expenses.push(C.normalizeExpense(entry)),'지출을 기록했어요.');closeSheet(true,true);}catch(err){formError(err.message)}};
}
function cashSheet(){showSheet('현금 관리',`<form id="cashForm"><label class="field">처음 준비한 현금 NT$<input name="opening" type="number" inputmode="decimal" min="0" max="10000000" step="0.01" value="${state.settings.cashOpening??''}" required><small id="cashOpeningKrw">${state.settings.cashOpening===null?'초기 현금을 입력하세요.':inlineMoney(state.settings.cashOpening)}</small></label><label class="field">추가 인출·충전 반영 누계 NT$<input name="added" type="number" inputmode="decimal" min="-10000000" max="10000000" step="0.01" value="${state.settings.cashAdded}" required><small id="cashAddedKrw">${inlineMoney(state.settings.cashAdded)}</small><small>추가 인출은 +, 이지카드 충전 등 현금 전환은 −로 반영하세요. 은행 잔액과 자동 연동되지 않습니다.</small></label><p class="small">잔액 = 초기 현금 + 위 누계 − 현금 지출 기록.<br>지출 목록에 이미 현금 사용으로 기록했다면 누계에 다시 빼지 마세요.</p><p class="err" id="formError"></p><button class="btn primary full">저장</button></form>`);$('#cashForm [name=opening]').oninput=e=>{$('#cashOpeningKrw').textContent='약 '+fmt(krw(Number(e.target.value)||0))+'원';};$('#cashForm [name=added]').oninput=e=>{$('#cashAddedKrw').textContent='약 '+fmt(krw(Number(e.target.value)||0))+'원';};$('#cashForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),opening=Number(f.get('opening')),added=Number(f.get('added'));if(!Number.isFinite(opening)||opening<0||!Number.isFinite(added))return formError('현금을 확인하세요.');mutate(()=>{state.settings.cashOpening=opening;state.settings.cashAdded=added},'현금 기준을 저장했어요.');closeSheet(true,true)};}
function budgetSettings(){showSheet('쇼핑 예산',`<form id="budgetForm"><label class="field">위스키 예산 · 현금 NT$<input name="whisky" type="number" min="0" max="10000000" step="1" value="${state.settings.whisky}" required><small>${inlineMoney(state.settings.whisky)}</small></label><label class="field">선물·쇼핑 예산 NT$<input name="gifts" type="number" min="0" max="10000000" step="1" value="${state.settings.gifts}" required><small>${inlineMoney(state.settings.gifts)}</small></label><p class="small">원본처럼 선물 예산의 40%를 현금으로 가정해 권장 현금을 계산합니다.</p><p class="err" id="formError"></p><button class="btn primary full">저장</button></form>`);$('#budgetForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),whisky=Number(f.get('whisky')),gifts=Number(f.get('gifts'));if(!Number.isFinite(whisky)||whisky<0||!Number.isFinite(gifts)||gifts<0)return formError('예산을 확인하세요.');mutate(()=>{state.settings.whisky=whisky;state.settings.gifts=gifts},'쇼핑 예산을 변경했어요.');closeSheet(true,true)};}
/* ---------- Search, backup and settings ---------- */
function searchSheet(){if(!state.trip){toast('여행 파일을 먼저 불러와 주세요.');return;}showSheet('전체 검색',`<input id="globalSearch" type="search" placeholder="카발란, 예약, 택시…" aria-label="일정·장소·가이드 검색"><div id="globalResults" class="search-results"></div>`);$('#globalSearch').oninput=e=>{const q=e.target.value.trim().toLowerCase();if(!q){$('#globalResults').innerHTML='';return;}const items=state.trip.items.filter(x=>(x.title+' '+(x.notes||'')+' '+(x.body||'')).toLowerCase().includes(q)),places=Object.entries(state.trip.places).filter(([id,p])=>(p.n+' '+(p.zh||'')+' '+(p.addr||'')).toLowerCase().includes(q)),terms=Object.entries(state.trip.terms||{}).filter(([k,v])=>(v.t+' '+v.b).toLowerCase().includes(q));$('#globalResults').innerHTML=items.slice(0,25).map(x=>`<button class="btn" data-action="search-reveal" data-id="${esc(x.id)}"><b>${esc(x.title)}</b><div class="small">일정 · ${stamp(x.start,x.tz,true)}</div></button>`).join('')+places.slice(0,15).map(([id,p])=>`<button class="btn" data-action="place-info" data-place="${esc(id)}"><b>${esc(p.n)}</b><div class="small">장소 · ${esc(p.zh||'')}</div></button>`).join('')+terms.map(([k,v])=>`<button class="btn" data-term="${esc(k)}">가이드 · ${esc(v.t)}</button>`).join('')+((state.trip.guideHTML||'').toLowerCase().includes(q)?'<button class="btn" data-action="search-guide">가이드 본문에 검색어 있음 → 전체 가이드 보기</button>':'');if(!$('#globalResults').innerHTML)$('#globalResults').textContent='검색 결과가 없어요.';};}
function downloadJSON(obj,name){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
function exportBackup(){downloadJSON({...state,exportedAt:new Date().toISOString()},'타이베이_v2_백업_'+new Date().toISOString().slice(0,10)+'.json');toast('백업 파일을 저장했습니다. 개인 파일이므로 공개 업로드하지 마세요.');}
$('#importFile').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>8*1024*1024)throw Error('8MB 이하 JSON 파일만 가져올 수 있습니다.');const data=JSON.parse(await file.text());let candidate;if(data.kind==='taipei-trip-data'){C.validateTrip(data);candidate=emptyState();candidate.trip=C.clone(data);candidate.originalTrip=C.clone(data);candidate.settings={...state.settings};candidate.fx=state.fx;}else candidate=validateBackup(data);
 const apply=()=>{snapshot();state=candidate;if(state.trip)C.bindRouteAnchors(state.trip);scrollPositions.clear();recoveryNotice='';curDay=null;tab='home';openCards.clear();delayProposal=null;log('여행 파일 가져오기');persist();render();toast('여행 파일을 이 기기에 저장했어요.',true);};if(state.trip)confirmAction('파일을 불러올까요?','현재 일정·지출을 가져온 파일로 교체합니다. 먼저 백업을 권장합니다. 직후 되돌리기도 가능합니다.',apply);else apply();
 }catch(err){toast('불러오기 실패: '+err.message);}};
function settingsSheet(){showSheet('설정·백업',`<form id="settingsForm"><div class="grid2"><label class="field">화면<select name="theme">${[['system','기기 설정'],['light','밝게'],['dark','어둡게']].map(([v,n])=>`<option value="${v}" ${state.settings.theme===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">최소 휴식 · 분<input name="minRest" type="number" min="10" max="120" step="5" value="${state.settings.minRest}" required></label></div><label class="field">고정 예약 도착 여유 · 분<input name="reservationBuffer" type="number" min="0" max="180" step="5" value="${state.settings.reservationBuffer}" required></label><label class="check"><input name="motion" type="checkbox" ${state.settings.motion?'checked':''}><span>짧은 터치 모션<small>기기의 동작 줄이기 설정을 우선합니다.</small></span></label><label class="check"><input name="haptics" type="checkbox" ${state.settings.haptics?'checked':''}><span>지원 기기에서 짧은 진동</span></label><label class="check"><input name="autoDelay" type="checkbox" ${state.settings.autoDelay?'checked':''}><span>명시적으로 허용: 지연 제안 자동 적용<small>기본은 제안만 생성하고 내가 적용합니다. 이 항목을 체크해 저장한 경우에만 안전 검사 후 자동 적용합니다. 내가 ‘지금 시작’한 일정과 완료 시각만 근거로 사용합니다. 앱 화면 활성 중에 확인하며, 백그라운드·항공·실시간 교통 추적은 하지 않아요.</small></span></label><p class="err" id="formError"></p><button class="btn primary full">설정 저장</button></form><div class="sep"></div><h3>내 데이터</h3><div class="actions"><button class="btn" data-action="export">백업 저장</button><button class="btn" data-action="import">백업·여행 파일 불러오기</button><button class="btn" data-action="legacy">v1 체크 가져오기</button><button class="btn danger" data-action="restore-original">원본 일정 복원</button></div><p class="small" style="margin-top:10px">백업에는 개인 일정·지출이 들어 있습니다. 기기 변경 시 직접 가져오세요. 현재 파일 URL과 배포 URL의 저장공간은 다릅니다.</p><div class="sep"></div><h3>앱·오프라인</h3><div class="actions"><button class="btn" data-action="install">홈 화면 설치</button><button class="btn" data-action="cache-info">오프라인 준비 확인</button><button class="btn" data-action="check-update">업데이트 확인</button><button class="btn" data-action="persist-storage">저장 유지 요청</button>${swReg?.waiting?'<button class="btn primary" data-action="apply-update">새 버전 적용</button>':''}</div><p class="small" style="margin-top:12px">v${VERSION} · 일정·지출의 외부 자동 전송 없음.<br>환율 제공처에는 통화 조회 요청, 지도에는 직접 선택한 출발·도착지가 전달됩니다.</p>`);
 $('#settingsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),minRest=Number(f.get('minRest')),guard=Number(f.get('reservationBuffer'));if(minRest<10||minRest>120||guard<0||guard>180)return formError('시간 범위를 확인하세요.');mutate(()=>{Object.assign(state.settings,{theme:f.get('theme'),minRest,reservationBuffer:guard,motion:f.has('motion'),haptics:f.has('haptics'),autoDelay:f.has('autoDelay'),autoDelayConsentVersion:f.has('autoDelay')?1:0})},'설정을 저장했어요.');closeSheet(true,true);};}
function importLegacy(){try{const prep=JSON.parse(localStorage.getItem('tpe26:prep')||'null'),done=JSON.parse(localStorage.getItem('tpe26:done')||'null'),r=JSON.parse(localStorage.getItem('tpe26:rate')||'null');if(!prep&&!done&&!r){toast('이 출처에 v1 기록이 없습니다. 기존 앱과 주소가 다르면 자동으로 읽을 수 없어요.');return;}if(!state.trip){toast('여행 데이터를 먼저 가져오세요.');return;}mutate(()=>{if(prep&&typeof prep==='object')state.prep=prep;if(done)state.trip.items.forEach(x=>{if(done[x.id])x.status='done'});if(Number.isFinite(r)&&r>0){state.settings.manualRate=r;state.settings.rateMode='manual'}},'같은 출처의 v1 체크·환율을 가져왔어요.');}catch(e){toast('v1 기록 형식을 확인할 수 없습니다.');}}
/* ---------- Offline/install/update, no silent resets ---------- */
async function checkCache(){if(!navigator.serviceWorker?.controller){cacheReady=false;updateTop();return false;}
 try{const result=await new Promise((resolve,reject)=>{const ch=new MessageChannel(),timer=setTimeout(()=>reject(Error('timeout')),5000);ch.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data)};navigator.serviceWorker.controller.postMessage({type:'CACHE_STATUS'},[ch.port2]);});cacheReady=!!result.ready;cacheVersion=result.version||'';}catch(e){cacheReady=false;}updateTop();return cacheReady;}
async function cacheInfo(){await checkCache();showSheet('오프라인 준비 상태',`<div class="notice ${cacheReady?'':'warn'}"><b>${cacheReady?'앱 필수 파일 저장 완료':'아직 오프라인 준비가 확인되지 않았습니다.'}</b></div><p>앱 파일: ${cacheReady?'준비됨 · '+esc(cacheVersion):'미확인'}<br>개인 일정: ${state.trip?'이 기기에 '+state.trip.items.length+'개':'불러오기 필요'}<br>환율: ${state.fx?'마지막 성공값 저장됨':'최신 조회 기록 없음 · 임시 기준 사용'}</p><p class="small">${location.protocol==='file:'?'다운로드 HTML은 미리보기입니다. 설치형 앱과 Service Worker 캐시는 HTTPS 배포 주소에서 동작합니다.':'처음 온라인으로 열어 저장 완료를 확인한 뒤 비행기 모드에서 재실행해 보세요.'}<br><br>지도·배달·예약 외부 사이트는 별도입니다. 기기 저장공간 부족이나 사이트 데이터 삭제 시 캐시·기록이 지워질 수 있어 백업을 권장합니다.</p><div class="actions"><button class="btn" data-action="check-update">온라인에서 다시 확인</button><button class="btn" data-action="export">데이터 백업</button></div>`);}
async function installApp(){if(matchMedia('(display-mode: standalone)').matches){toast('이미 앱 화면으로 실행 중입니다.');return;}if(installPrompt){try{await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}catch(e){toast('브라우저 메뉴에서 앱 설치를 선택하세요.');}return;}showSheet('홈 화면에 설치',`<p><b>갤럭시 Chrome</b>에서 배포 주소를 연 뒤 우측 상단 메뉴에서 <b>홈 화면에 추가 → 설치</b> 또는 <b>앱 설치</b>를 선택하세요.</p><p class="small">브라우저 버전과 설치 상태에 따라 메뉴 이름이 다릅니다. 다운로드한 HTML이나 채팅 미리보기 화면에서는 설치되지 않습니다.</p><button class="btn" data-action="cache-info">오프라인 준비 확인</button>`);}
let lastUpdateCheck=0,appUpdateApplying=false;
function updateBanner(){let b=$('#appUpdateBanner');if(!b){b=document.createElement('div');b.id='appUpdateBanner';b.className='update-banner';b.setAttribute('role','status');b.innerHTML='<div><b>새 버전이 준비됐어요</b><small>일정·지출은 그대로 유지돼요</small></div><button class="btn primary" id="quickUpdate">업데이트하기</button>';$('#top .wrap').appendChild(b);$('#quickUpdate').onclick=applyAppUpdate;}b.hidden=!swReg?.waiting;}
async function checkAppUpdate(force=false){if(!swReg||!navigator.onLine)return;const now=Date.now();if(!force&&now-lastUpdateCheck<30*60000){updateBanner();return;}lastUpdateCheck=now;try{await swReg.update();updateBanner();}catch(e){if(force)toast('업데이트를 확인하지 못했어요. 인터넷 연결 후 다시 눌러 주세요.');}}
function applyAppUpdate(){if(appUpdateApplying)return;if($('#sheet').open&&isSheetDirty()){toast('입력 중인 내용을 먼저 저장하거나 닫아 주세요.');return;}const waiting=swReg?.waiting;if(!waiting){toast('아직 새 버전이 준비되지 않았어요.');checkAppUpdate(true);return;}persist();if(!storageOK){toast('저장에 실패해서 업데이트를 중단했어요. 먼저 데이터를 백업해 주세요.');return;}appUpdateApplying=true;const button=$('#quickUpdate');if(button)button.disabled=true;let timer;
 const finished=()=>{clearTimeout(timer);appUpdateApplying=false;if($('#sheet').open&&isSheetDirty()){toast('새 버전이 준비됐어요. 입력을 저장한 뒤 앱을 다시 열어 주세요.');return;}location.reload();};
 navigator.serviceWorker.addEventListener('controllerchange',finished,{once:true});timer=setTimeout(()=>{navigator.serviceWorker.removeEventListener('controllerchange',finished);appUpdateApplying=false;if(button)button.disabled=false;toast('업데이트 적용을 확인하지 못했어요. 잠시 후 다시 시도해 주세요.');},15000);
 try{waiting.postMessage({type:'SKIP_WAITING'});}catch(e){clearTimeout(timer);navigator.serviceWorker.removeEventListener('controllerchange',finished);appUpdateApplying=false;if(button)button.disabled=false;toast('업데이트를 적용하지 못했어요. 다시 확인해 주세요.');}
}

async function setupSW(){if(window.TAIPEI_STANDALONE_PREVIEW)return;if(!('serviceWorker' in navigator)||!(location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname)))return;
 try{swReg=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});swReg.addEventListener('updatefound',()=>{const w=swReg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller){updateBanner();toast('새 앱 버전이 준비됐어요. 위의 업데이트 버튼을 눌러 주세요.');}});});navigator.serviceWorker.addEventListener('controllerchange',()=>checkCache());await navigator.serviceWorker.ready;await checkCache();updateBanner();checkAppUpdate();}catch(e){cacheReady=false;updateTop();console.warn('Offline setup:',e.message);}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('appinstalled',()=>{installPrompt=null;toast('앱이 설치되었습니다.');});
/* ---------- Delegated UI events ---------- */
document.addEventListener('click',e=>{
 const b=e.target.closest('button,[data-action],a');if(!b)return;if(b.tagName==='BUTTON'&&b.type==='submit'&&b.form&&!b.dataset.action)return;
 if(b.matches('button,.btn'))feedback();
 if(b.dataset.tab){go(b.dataset.tab);return;}
 if(b.dataset.day){selectDay(b.dataset.day);return;}
 if(b.dataset.filter){if(placeFilter===b.dataset.filter)return;rememberScroll();placeFilter=b.dataset.filter;render();restoreScroll();return;}
 if(b.dataset.term){const t=state.trip?.terms?.[b.dataset.term];if(t)showSheet(t.t,`<div class="rich">${rich(t.b)}</div>${sourceNote()}`);return;}
 const a=b.dataset.action,id=b.dataset.id,p=b.dataset.place;if(!a)return;
 try{switch(a){
 case 'undo':undo();break;case 'close':closeSheet();break;
 case 'plan':go('plan');break;case 'prep':navigateMore('prep');break;
 case 'more-page':navigateMore(b.dataset.page);break;case 'more-back':navigateMore('');break;
 case 'settings':settingsSheet();break;case 'import':$('#importFile').click();break;case 'export':exportBackup();break;case 'legacy':importLegacy();break;
 case 'install':installApp();break;case 'cache-info':cacheInfo();break;
 case 'persist-storage':if(navigator.storage?.persist)navigator.storage.persist().then(ok=>toast(ok?'저장 유지 요청이 허용되었습니다. 별도 백업도 권장합니다.':'브라우저가 영구 저장을 허용하지 않았어요. 백업해 주세요.'));else toast('이 환경에서 지원되지 않습니다.');break;
 case 'check-update':checkAppUpdate(true);break;
 case 'apply-update':applyAppUpdate();break;
 case 'rate-settings':rateSettings();break;case 'refresh-rate':refreshRate(true);break;
 case 'editmode':editing=!editing;render();break;case 'add':editor();break;case 'add-place':editor(null,p);break;case 'edit':editor(id);break;
 case 'toggle-event':{const el=document.getElementById('event-'+id),open=!el.classList.contains('open');el.classList.toggle('open',open);b.setAttribute('aria-expanded',String(open));el.querySelector('.expand').inert=!open;if(open)openCards.add(id);else openCards.delete(id);break;}
 case 'reveal':reveal(id);break;case 'search-reveal':closeSheet(true,true);reveal(id);break;
 case 'search-guide':closeSheet(true,true);tab='more';morePage='guide';render();break;
 case 'start':case 'done':case 'skip':case 'unmark':case 'cancel-item':markItem(id,a);break;
 case 'delete':{const x=getItem(id);if(x)confirmAction('일정을 삭제할까요?',x.title+' · 실제 예약은 취소되지 않으며 직후 되돌릴 수 있습니다.',()=>mutate(()=>{x.status='skipped';C.repairRoutes(state.trip,x.dayId,id);state.trip.items=state.trip.items.filter(i=>i.id!==id)},'일정을 삭제했어요.'));break;}
 case 'duplicate':{let copyId;mutate(()=>{const result=C.duplicateVisit(state.trip,id);state.trip=result.trip;copyId=result.id;openCards.add(copyId)},'방문 일정을 복제했어요. 예약 확정은 승계하지 않습니다.');break;}
 case 'up':case 'down':mutate(()=>{state.trip=C.reorder(state.trip,curDay,id,a==='up'?-1:1)},'순서를 변경했어요. 시간·경로를 확인하세요.');break;
 case 'route':routeSheet(id);break;case 'place-route':routeSheet(null,p);break;case 'route-day':dayRoutes();break;case 'driver':driver(p,id||null);break;case 'place-info':placeSheet(p,id||null);break;case 'english':englishView();break;case 'conversation':conversationHome();break;
 case 'expense':expenseSheet(id||null);break;case 'cash':cashSheet();break;case 'budget-settings':budgetSettings();break;
 case 'delete-expense':confirmAction('지출 기록을 삭제할까요?','예산·현금 잔액에서도 해당 기록이 제외됩니다.',()=>mutate(()=>{state.expenses=state.expenses.filter(x=>x.id!==id)},'지출 기록을 삭제했어요.'));break;
 case 'delay':delaySheet(id);break;case 'delay-review':reviewDelay();break;case 'dismiss-delay':delayProposal=null;closeSheet(true,true);render(false);break;
 case 'prep-reset':confirmAction('준비 체크를 초기화할까요?','예약 자체는 취소되지 않습니다.',()=>mutate(()=>{state.prep={}},'준비 체크를 초기화했어요.'));break;
 case 'restore-original':if(!state.originalTrip){toast('보관된 원본 일정이 없습니다.');break;}confirmAction('원본 일정으로 복원할까요?','일정·완료·메모는 최초 데이터로 복원합니다. 지출·준비 체크·환율 설정은 유지합니다.',()=>mutate(()=>{state.trip=C.clone(state.originalTrip);delayProposal=null;curDay=null},'원본 일정을 복원했어요.'));break;
 case 'conflicts':showSheet('시간 겹침 확인',`<div class="stack">${C.conflicts(state.trip,curDay).map(c=>`<div class="notice warn"><b>${esc(getItem(c.a)?.title)}</b><br>↔ ${esc(getItem(c.b)?.title)}<br>${c.minutes}분 겹침 · 원본의 겹침도 포함<button class="btn full" data-action="edit" data-id="${esc(c.b)}">뒤 일정 시간 편집</button></div>`).join('')}</div>`);break;
 }}catch(err){toast(err.message||'작업에 실패했어요.');}
});
document.addEventListener('change',e=>{if(e.target.dataset.prep){const key=e.target.dataset.prep,checked=e.target.checked;snapshot();if(checked)state.prep[key]=1;else delete state.prep[key];persist();const focusId=key;render(false);$$('[data-prep]').find(x=>x.dataset.prep===focusId)?.focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(e.target.id==='placeSearch'){query=e.target.value;const start=e.target.selectionStart;const html=placesView();const doc=new DOMParser().parseFromString(html,'text/html');$('#placesList').innerHTML=doc.querySelector('#placesList').innerHTML;}});
$('#undoBtn').onclick=undo;
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.closest('input,textarea,[contenteditable=true]')&&!$('#sheet').open){e.preventDefault();undo();}});
 $('#fxBtn').onclick=calculator;$('#searchBtn').onclick=searchSheet;$('#settingsBtn').onclick=settingsSheet;$('#cacheBtn').onclick=cacheInfo;
/* Pointer-axis locking lets a swipe begin on an accordion card, without
   converting taps, vertical scrolling or editor/dragger gestures into day changes. */
let swipe=null,sortDrag=null;
$('#main').addEventListener('pointerdown',e=>{
 if(!e.isPrimary||e.button!==0)return;
 const handle=e.target.closest('[data-drag-id]');
 if(handle&&editing&&!$('#sheet').open){sortDrag={id:handle.dataset.dragId,pointer:e.pointerId,startY:e.clientY,y:e.clientY,target:null,moved:false};handle.setPointerCapture(e.pointerId);e.preventDefault();return;}
 if(tab!=='plan'||editing||$('#sheet').open||e.target.closest('input,select,textarea,a,summary,[contenteditable=true],button:not(.event-summary)'))return;
 swipe={pointer:e.pointerId,x:e.clientX,y:e.clientY,time:Date.now(),axis:null};
});
$('#main').addEventListener('pointermove',e=>{
 if(sortDrag&&sortDrag.pointer===e.pointerId){
  sortDrag.y=e.clientY;if(Math.abs(e.clientY-sortDrag.startY)>10)sortDrag.moved=true;
  const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.event');
  $$('.drop-target').forEach(el=>el.classList.remove('drop-target'));
  const candidate=target?getItem(target.id.slice(6)):null;
  sortDrag.target=candidate&&C.stop(candidate)&&candidate.status==='pending'&&!C.protectedItem(candidate)?candidate.id:null;
  if(sortDrag.target)target.classList.add('drop-target');
  e.preventDefault();return;
 }
 if(!swipe||swipe.pointer!==e.pointerId)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;
 if(!swipe.axis){if(Math.abs(dy)>14&&Math.abs(dy)>=Math.abs(dx))swipe.axis='vertical';else if(Math.abs(dx)>18&&Math.abs(dx)>Math.abs(dy)*1.8)swipe.axis='horizontal';}
 if(swipe.axis==='horizontal')e.preventDefault();
});
function finishMainPointer(e,cancel=false){
 if(sortDrag&&sortDrag.pointer===e.pointerId){const d=sortDrag;sortDrag=null;$$('.drop-target').forEach(el=>el.classList.remove('drop-target'));if(d.moved)suppressClickUntil=Date.now()+450;if(!cancel&&d.moved&&d.target&&d.target!==d.id){try{mutate(()=>{state.trip=C.reorderTo(state.trip,curDay,d.id,d.target)},'방문 순서를 변경했어요. 새 이동시간·요금은 미확정입니다.');}catch(err){toast(err.message);}}return;}
 if(!swipe||swipe.pointer!==e.pointerId)return;const d=swipe;swipe=null;if(cancel||d.axis!=='horizontal')return;
 const dx=e.clientX-d.x,dy=e.clientY-d.y;if(Math.abs(dx)<70||Math.abs(dx)<Math.abs(dy)*1.8||Date.now()-d.time>900)return;
 suppressClickUntil=Date.now()+450;const n=state.trip.days.findIndex(x=>x.id===curDay)+(dx<0?1:-1);
 if(n>=0&&n<state.trip.days.length){selectDay(state.trip.days[n].id);feedback();}
}
$('#main').addEventListener('pointerup',e=>finishMainPointer(e));$('#main').addEventListener('pointercancel',e=>finishMainPointer(e,true));
document.addEventListener('click',e=>{if(Date.now()<suppressClickUntil&&e.target.closest('#main')){e.preventDefault();e.stopImmediatePropagation();return;}
 if(isSheetDirty()&&e.target.closest('#sheet [data-action]')&&!['close','export'].includes(e.target.closest('[data-action]').dataset.action)){e.preventDefault();e.stopImmediatePropagation();toast('입력을 먼저 저장하거나 닫아 주세요.');}
},true);
$('#main').addEventListener('keydown',e=>{const h=e.target.closest('[data-drag-id]');if(!h||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();try{mutate(()=>{state.trip=C.reorder(state.trip,curDay,h.dataset.dragId,e.key==='ArrowUp'?-1:1)},'방문 순서를 변경했어요.');document.querySelector('[data-drag-id="'+CSS.escape(h.dataset.dragId)+'"]')?.focus({preventScroll:true});}catch(err){toast(err.message);}});
window.addEventListener('online',()=>{updateTop();refreshRate();checkAppUpdate();});window.addEventListener('offline',()=>updateTop());
document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateTop();refreshRate();checkAppUpdate();autoCheckDelay();if(!$('#sheet').open)render(false);}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const incoming=validateBackup(JSON.parse(e.newValue));if($('#sheet').open){toast('다른 창에서 변경되었습니다. 입력을 마친 뒤 새로고침해 주세요.');return;}state=incoming;if(state.trip)C.bindRouteAnchors(state.trip);delayProposal=null;undoStack.length=0;render(false);}catch(err){toast('다른 창의 데이터 형식을 확인할 수 없습니다.');}}});
setInterval(()=>{autoCheckDelay();updateTop();if(!document.hidden&&!$('#sheet').open&&tab==='home')render(false);},30000);
persist();render();refreshRate();setupSW();
